package co.edu.unicauca.lisw2t5g02.domain.user;
import java.util.Objects;
public class User {private int id;private String username,name,email,passwordHash;private Role role;private UserState state;public User(){} public User(int id,String username,String name,Role role,UserState state,String passwordHash){this.id=id;this.username=username;this.name=name;this.role=role;this.state=state;this.passwordHash=passwordHash;}public int getId(){return id;}public void setId(int v){id=v;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public Role getRole(){return role;}public void setRole(Role v){role=v;}public UserState getState(){return state;}public void setState(UserState v){state=v;}public String getPasswordHash(){return passwordHash;}public void setPasswordHash(String v){passwordHash=v;}@Override public boolean equals(Object o){return o instanceof User u&&id==u.id;}@Override public int hashCode(){return Objects.hash(id);} @Override public String toString(){return name+" ("+role+")";}}
